"""Base64 icon usage: paste a raw Base64 string or a data URI
(e.g., "data:image/x-icon;base64,AAAB..."). The data URI prefix
will be removed automatically by icon_from_base64()."""


# ===== Base64 Application Icon (placeholder) =====
# Place your icon text here after converting it to Base64 (without the data:URI prefix)
# Example format:
#   ICON_BASE64 = "AAABAAEA..."  (long Base64 string)
# If you have a data URI like: "data:image/x-icon;base64,AAAB..." it is OK,
# the prefix will be stripped automatically.
ICON_BASE64 = ""


def icon_from_base64(b64_text: str) -> QIcon:
    """Create a QIcon from a base64-encoded image string.

    - Accepts raw base64 or a data URI (e.g., 'data:image/x-icon;base64,...').
    - Returns an empty QIcon() if input is empty or invalid.
    """
    try:
        if not b64_text or not b64_text.strip():
            return QIcon()

        data_str = b64_text.strip()
        # Strip data URI prefix if present
        if ";base64" in data_str.lower() and "," in data_str:
            data_str = data_str.split(",", 1)[1]

        raw = base64.b64decode(data_str)
        pix = QPixmap()
        if pix.loadFromData(raw):
            return QIcon(pix)
    except Exception:
        pass
    return QIcon()

def is_valid_ip(ip):
    pattern = r"^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$"
    return re.match(pattern, ip) is not None


