def clean_output(output, cmd):
    return re.sub(fr"{re.escape(cmd)}\r?\n", "", output).strip()


def wait_for_prompt(shell, timeout=10):
    end_time = time.time() + timeout
    output = ""
    while time.time() < end_time and not stop_event.is_set():
        if shell.recv_ready():
            output += shell.recv(65535).decode(errors="ignore")
            if re.search(r"[#>]$", output.split("\n")[-1]):
                return output
        time.sleep(0.1)
    return output


def execute_commands():
    try:
        invalid_ips = []
        failed_ips = []
        error_messages = []
        valid_ips = []

        username = username_entry.text()
        password = password_entry.text()
        enable_pass = enable_password_entry.text()
        ip_file = ip_file_path.text()
        port = port_entry.value()
        delay = delay_var.value()
        commands = [
            cmd.strip() for cmd in command_text.toPlainText().splitlines() if cmd.strip()
        ]

        if not all([username, password, ip_file, commands]):
            comms.update_output.emit("Error: Please fill all required fields!")
            return

        try:
            with open(ip_file, "r") as f:
                ips = [line.strip() for line in f]

            for ip in ips:
                if is_valid_ip(ip):
                    valid_ips.append(ip)
                else:
                    invalid_ips.append(ip)

            comms.progress_max.emit(len(valid_ips))
            comms.update_errors.emit(invalid_ips, [], [])

        except Exception as e:
            comms.update_output.emit(f"ðŸ“ File Error: {str(e)}")
            return

        for idx, ip in enumerate(valid_ips, 1):
            if stop_event.is_set():
                break

            comms.update_output.emit(f"\nðŸ”— Attempting connection to {ip}...")

            try:
                ssh = paramiko.SSHClient()
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

                # Increase timeouts and set keepalive
                transport = paramiko.Transport((ip, port))
                transport.start_client()
                transport.auth_password(username, password)
                if transport.is_authenticated():
                    transport.set_keepalive(30)
                    ssh._transport = transport
                else:
                    raise paramiko.AuthenticationException()

                # Create interactive shell
                shell = ssh.invoke_shell()
                shell.settimeout(15)

                # Handle enable mode
                if enable_pass:
                    shell.send("enable\n")
                    enable_output = wait_for_prompt(shell)
                    if "Password" in enable_output:
                        shell.send(f"{enable_pass}\n")
                        enable_result = wait_for_prompt(shell)
                        if "#" not in enable_result:
                            raise Exception("Failed to enter privileged mode")

                # Execute commands
                for cmd in commands:
                    if stop_event.is_set():
                        break

                    shell.send(f"{cmd}\n")
                    output = wait_for_prompt(shell)
                    cleaned_output = clean_output(output, cmd)

                    if cleaned_output:
                        comms.update_output.emit(f"[{ip}] {cmd}\n{cleaned_output}")
                    else:
                        comms.update_output.emit(f"[{ip}] {cmd} (executed but no output)")

                ssh.close()
                comms.update_output.emit(f"âœ… Successfully completed: {ip}")

            except Exception as e:
                error_msg = f"âŒ Connection failed: {ip} - {str(e)}"
                failed_ips.append(ip)
                error_messages.append(str(e))
                comms.update_output.emit(error_msg)

            comms.progress_update.emit(idx)

        comms.update_errors.emit(invalid_ips, failed_ips, error_messages)

    except Exception as e:
        comms.update_output.emit(f"ðŸ”¥ Critical error: {str(e)}")
    finally:
        comms.toggle_buttons.emit(True, False)
        stop_event.clear()


def start_execution():
    # Licensing: Block start if trial expired or clock tampering detected
    try:
        allowed = license_manager.can_start()
    except Exception:
        allowed = True  # Fail open on unexpected errors to avoid blocking users

    if not allowed:
        QMessageBox.warning(
            window,
            "Trial expired",
            "The trial period has ended (or clock tampering was detected).\n"
            "Please activate from the \"Activation\" button.",
            QMessageBox.Ok,
        )
        return

    stop_event.clear()
    comms.toggle_buttons.emit(False, True)
    threading.Thread(target=execute_commands, daemon=True).start()


def stop_execution():
    stop_event.set()
    QMessageBox.information(
        window,
        "Stop Execution",
        """Wait a few seconds<br>
        """,
        QMessageBox.Ok
    )
    comms.update_output.emit("\nðŸ›‘ Operation stopped by user!")


def save_output():
    try:
        # Check if there's content to save
        if not output_text.toPlainText().strip():
            comms.update_output.emit("âš ï¸ No output to save!")
            return

        # Get save path
        file_path, _ = QFileDialog.getSaveFileName(
            None, "Save Output", "HKssh_Results.txt", "Text Files (*.txt)"
        )

        if file_path:
            # Use 'with' statement for safe file handling
            with open(file_path, "w", encoding="utf-8") as f:  # Specify encoding
                f.write(output_text.toPlainText())

            # Confirm save operation
            comms.update_output.emit(f"\nðŸ’¾ Output successfully saved to:\n{file_path}")

    except Exception as e:
        error_msg = f"ðŸ”¥ Save Failed: {str(e)}"
        comms.update_output.emit(error_msg)
    finally:
        # Ensure application remains responsive
        QApplication.processEvents()


