"""
===== Licensing / Trial Manager =====
Offline 30-day trial and activation tied to a hardware fingerprint.
"""

SETTINGS_ORG = "HKssh"
SETTINGS_APP = "HKsshTool"
TRIAL_DAYS = 30
LICENSE_CODE = "*****"
_HMAC_SECRET = b"*****"


def _read_machine_guid() -> str:
    try:
        if reg is None:
            return ""
        key_path = r"SOFTWARE\Microsoft\Cryptography"
        with reg.OpenKey(reg.HKEY_LOCAL_MACHINE, key_path, 0, reg.KEY_READ | getattr(reg, 'KEY_WOW64_64KEY', 0)) as k:
            v, _ = reg.QueryValueEx(k, "MachineGuid")
            return str(v).strip()
    except Exception:
        return ""


def _try_exec(cmd: list) -> str:
    try:
        out = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
        return out.decode(errors="ignore")
    except Exception:
        return ""


def _parse_wmic_value(text: str, headers=("serialnumber", "uuid")) -> str:
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    for l in lines:
        if l.lower() in headers:
            continue
        return l
    return ""


def get_hardware_fingerprint() -> str:
    values = []

    # PowerShell (try if available)
    ps = shutil.which("powershell")
    if ps:
        bios_sn = _try_exec([ps, "-NoProfile", "-Command", "(Get-CimInstance -ClassName Win32_BIOS).SerialNumber"]) or ""
        cs_uuid = _try_exec([ps, "-NoProfile", "-Command", "(Get-CimInstance -ClassName Win32_ComputerSystemProduct).UUID"]) or ""
        baseboard_sn = _try_exec([ps, "-NoProfile", "-Command", "(Get-CimInstance -ClassName Win32_BaseBoard).SerialNumber"]) or ""
        values += [bios_sn.strip(), cs_uuid.strip(), baseboard_sn.strip()]

    # WMIC (fallback)
    wmic = shutil.which("wmic")
    if wmic:
        bios = _parse_wmic_value(_try_exec([wmic, "bios", "get", "serialnumber"]))
        uuid = _parse_wmic_value(_try_exec([wmic, "csproduct", "get", "uuid"]))
        board = _parse_wmic_value(_try_exec([wmic, "baseboard", "get", "serialnumber"]))
        values += [bios, uuid, board]

    # Windows MachineGuid
    values.append(_read_machine_guid())

    # Additional non-critical hints
    values.append(platform.node())
    values.append(os.environ.get("COMPUTERNAME", ""))

    joined = "|".join([v for v in values if v]) or "fallback-unknown"
    return hashlib.sha256(joined.encode("utf-8", errors="ignore")).hexdigest()


def get_bios_serial_number() -> str:
    """Return BIOS SerialNumber if available, else '-'.
    Tries PowerShell CIM first, then WMIC as fallback.
    """
    ps = shutil.which("powershell")
    if ps:
        out = _try_exec([ps, "-NoProfile", "-Command", "(Get-CimInstance -ClassName Win32_BIOS).SerialNumber"]) or ""
        out = out.strip()
        if out:
            return out
    wmic = shutil.which("wmic")
    if wmic:
        serial = _parse_wmic_value(_try_exec([wmic, "bios", "get", "serialnumber"])) or ""
        serial = serial.strip()
        if serial:
            return serial
    return "-"


def _now_utc_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def _hmac_hex(data: str) -> str:
    return hmac.new(_HMAC_SECRET, data.encode("utf-8"), hashlib.sha256).hexdigest()


def _parse_iso(value: str) -> datetime.datetime:
    try:
        return datetime.datetime.fromisoformat(value)
    except Exception:
        return datetime.datetime.now(datetime.timezone.utc)


class LicenseManager:
    def __init__(self, settings: QSettings):
        self.settings = settings
        self.fingerprint = get_hardware_fingerprint()
        self.bios_serial = get_bios_serial_number()
        self.data = {
            "first_run": _now_utc_iso(),
            "last_run": _now_utc_iso(),
            # Rolling 30-day window: valid_until defines when usage expires
            "valid_until": "",
            # Activation bookkeeping (count and last time)
            "activation_count": 0,
            "last_activation_on": "",
            # Legacy flags kept for backward-compatibility (ignored by logic)
            "activated": False,
            "activated_on": "",
            "fingerprint": self.fingerprint,
            "blocked": False,
        }
        self._load_and_validate()
        self._detect_clock_tamper_and_update_last_run()
        self._ensure_fingerprint_binding()
        self._ensure_valid_until_and_migrate()
        self._persist()

    def _persist(self):
        blob = json.dumps(self.data, separators=(",", ":"), sort_keys=True)
        mac = _hmac_hex(blob)
        self.settings.setValue("license_json", blob)
        self.settings.setValue("license_mac", mac)
        self.settings.sync()

    def _load_and_validate(self):
        blob = self.settings.value("license_json", "")
        mac = self.settings.value("license_mac", "")
        if not blob:
            return
        try:
            expected = _hmac_hex(blob)
            if not mac or mac != expected:
                self.data["blocked"] = True
                return
            loaded = json.loads(blob)
            if isinstance(loaded, dict):
                self.data.update(loaded)
        except Exception:
            self.data["blocked"] = True

    def _ensure_valid_until_and_migrate(self):
        """Ensure we have a valid_until and migrate legacy one-time activation
        to rolling 30-day extensions.
        """
        try:
            first_dt = _parse_iso(self.data.get("first_run", _now_utc_iso()))
        except Exception:
            first_dt = datetime.datetime.now(datetime.timezone.utc)
        now = datetime.datetime.now(datetime.timezone.utc)

        valid_until_str = self.data.get("valid_until", "")
        if not valid_until_str:
            # Initialize trial window from first run
            vu = first_dt + datetime.timedelta(days=TRIAL_DAYS)
            self.data["valid_until"] = vu.isoformat()

        # Migrate legacy unlimited activation to 30-day extension
        if self.data.get("activated"):
            act_on = self.data.get("activated_on", "")
            if act_on:
                base = _parse_iso(act_on)
            else:
                base = now
            migrated_vu = base + datetime.timedelta(days=TRIAL_DAYS)
            # Only extend forward if legacy implies later expiry
            current_vu = _parse_iso(self.data.get("valid_until", now.isoformat()))
            if migrated_vu > current_vu:
                self.data["valid_until"] = migrated_vu.isoformat()
            # Mark at least one activation
            try:
                self.data["activation_count"] = max(int(self.data.get("activation_count", 0)), 1)
            except Exception:
                self.data["activation_count"] = 1

    def _detect_clock_tamper_and_update_last_run(self):
        try:
            last = datetime.datetime.fromisoformat(self.data.get("last_run", _now_utc_iso()))
        except Exception:
            last = datetime.datetime.now(datetime.timezone.utc)
        now = datetime.datetime.now(datetime.timezone.utc)
        if now < last - datetime.timedelta(minutes=5):
            self.data["blocked"] = True
        self.data["last_run"] = _now_utc_iso()

    def _ensure_fingerprint_binding(self):
        stored_fp = self.data.get("fingerprint", "")
        if stored_fp and stored_fp != self.fingerprint:
            # New device/fingerprint -> restart trial window
            now = datetime.datetime.now(datetime.timezone.utc)
            self.data["fingerprint"] = self.fingerprint
            self.data["first_run"] = now.isoformat()
            self.data["last_run"] = now.isoformat()
            self.data["valid_until"] = (now + datetime.timedelta(days=TRIAL_DAYS)).isoformat()
            self.data["activation_count"] = 0
            self.data["last_activation_on"] = ""
            self.data["activated"] = False
            self.data["activated_on"] = ""
            self.data["blocked"] = False
        elif not stored_fp:
            self.data["fingerprint"] = self.fingerprint

    def days_used(self) -> int:
        # Kept for compatibility; not used for expiry anymore
        try:
            first = _parse_iso(self.data.get("first_run", _now_utc_iso()))
        except Exception:
            first = datetime.datetime.now(datetime.timezone.utc)
        today = datetime.datetime.now(datetime.timezone.utc)
        return max(0, (today.date() - first.date()).days)

    def days_remaining(self) -> int:
        try:
            vu = _parse_iso(self.data.get("valid_until", _now_utc_iso()))
        except Exception:
            vu = datetime.datetime.now(datetime.timezone.utc)
        now = datetime.datetime.now(datetime.timezone.utc)
        return max(0, (vu.date() - now.date()).days)

    def is_expired(self) -> bool:
        try:
            vu = _parse_iso(self.data.get("valid_until", _now_utc_iso()))
        except Exception:
            vu = datetime.datetime.now(datetime.timezone.utc)
        now = datetime.datetime.now(datetime.timezone.utc)
        return now > vu

    def is_blocked(self) -> bool:
        return bool(self.data.get("blocked"))

    def status(self) -> str:
        if self.is_blocked():
            return "blocked"
        if self.is_expired():
            return "expired"
        # Within window
        try:
            count = int(self.data.get("activation_count", 0))
        except Exception:
            count = 0
        return "trial" if count <= 0 else "active"

    def can_start(self) -> bool:
        return (not self.is_blocked()) and (not self.is_expired())

    def activate(self, code: str) -> bool:
        if code and code.strip() == LICENSE_CODE:
            now = datetime.datetime.now(datetime.timezone.utc)
            new_vu = now + datetime.timedelta(days=TRIAL_DAYS)
            self.data["valid_until"] = new_vu.isoformat()
            self.data["last_activation_on"] = now.isoformat()
            try:
                self.data["activation_count"] = int(self.data.get("activation_count", 0)) + 1
            except Exception:
                self.data["activation_count"] = 1
            # Clear block and ensure current fingerprint binding
            self.data["blocked"] = False
            self.data["fingerprint"] = self.fingerprint
            # Legacy flags no longer meaningful, keep false
            self.data["activated"] = False
            self.data["activated_on"] = ""
            self._persist()
            return True
        return False

    def human_status(self) -> str:
        st = self.status()
        if st == "active":
            return f"Status: Active — Remaining days: {self.days_remaining()}"
        if st == "trial":
            return f"Status: Trial — Remaining days: {self.days_remaining()} of {TRIAL_DAYS}"
        if st == "expired":
            return "Status: Expired — Please activate"
        return "Status: Blocked due to clock tampering — Please activate"

    def device_id(self) -> str:
        try:
            return (self.fingerprint or "").replace("-", "").upper()[:16]
        except Exception:
            return ""

    def info(self) -> dict:
        try:
            activation_count = int(self.data.get("activation_count", 0))
        except Exception:
            activation_count = 0
        st = self.status()
        lic_type = "Activated" if (activation_count > 0 and st != "expired") else ("Expired" if st == "expired" else "Trial")

        def fmt_iso_to_utc(iso_s: str) -> str:
            if not iso_s:
                return "-"
            try:
                dt = _parse_iso(iso_s).astimezone(datetime.timezone.utc)
                return dt.strftime("%Y-%m-%d %H:%M UTC")
            except Exception:
                return iso_s

        return {
            "status": st.title(),
            "type": lic_type,
            "days_remaining": self.days_remaining(),
            "activated_on": fmt_iso_to_utc(self.data.get("last_activation_on", "")),
            "expires": fmt_iso_to_utc(self.data.get("valid_until", "")),
            "device_id": self.device_id(),
            "bios_serial": getattr(self, 'bios_serial', '') or "-",
        }

class ActivationDialog(QDialog):
    def __init__(self, license_mgr: 'LicenseManager', parent=None, on_activated=None):
        super().__init__(parent)
        self.setWindowTitle("Activation")
        self.license_mgr = license_mgr
        self.on_activated = on_activated

        layout = QVBoxLayout()
        self.status_label = QLabel(self.license_mgr.human_status())
        layout.addWidget(self.status_label)

        # Detailed license info as labels
        self.lbl_status_detail = QLabel("")
        self.lbl_license_type = QLabel("")
        self.lbl_days_remaining = QLabel("")
        self.lbl_activated = QLabel("")
        self.lbl_expires = QLabel("")
        self.lbl_device_id = QLabel("")
        self.lbl_bios_serial = QLabel("")

        layout.addWidget(self.lbl_status_detail)
        layout.addWidget(self.lbl_license_type)
        layout.addWidget(self.lbl_days_remaining)
        layout.addWidget(self.lbl_activated)
        layout.addWidget(self.lbl_expires)
        layout.addWidget(self.lbl_device_id)
        layout.addWidget(self.lbl_bios_serial)

        self._refresh_details()

        self.activate_btn = QPushButton("Activate")
        self.activate_btn.clicked.connect(self._show_activation_form)
        layout.addWidget(self.activate_btn)

        self.serial_input = QLineEdit()
        self.serial_input.setPlaceholderText("Enter activation serial")
        self.serial_input.setEchoMode(QLineEdit.Password)
        self.serial_input.setText("")
        self.serial_input.setVisible(False)
        layout.addWidget(self.serial_input)

        self.confirm_btn = QPushButton("Confirm Activation")
        self.confirm_btn.setVisible(False)
        self.confirm_btn.clicked.connect(self._confirm_activation)
        layout.addWidget(self.confirm_btn)

        close_btn = QPushButton("Close")
        close_btn.clicked.connect(self.accept)
        layout.addWidget(close_btn)

        self.setLayout(layout)

    def _show_activation_form(self):
        self.serial_input.setVisible(True)
        self.confirm_btn.setVisible(True)

    def _confirm_activation(self):
        code = self.serial_input.text().strip()
        if self.license_mgr.activate(code):
            QMessageBox.information(self, "Success", "Activated successfully.")
            if callable(self.on_activated):
                self.on_activated()
            self._refresh_details()
            self.accept()
        else:
            QMessageBox.warning(self, "Failed", "Invalid serial.")

    def _refresh_details(self):
        try:
            info = self.license_mgr.info()
        except Exception:
            info = {
                "status": "-",
                "type": "-",
                "days_remaining": 0,
                "activated_on": "-",
                "expires": "-",
                "device_id": "",
                "bios_serial": "-",
            }

        status_line = f"License Status: {info['status']} ({info['days_remaining']} day(s) remaining)"
        self.lbl_status_detail.setText(status_line)
        self.lbl_license_type.setText(f"License Type: {info['type']}")
        self.lbl_days_remaining.setText(f"Days Remaining: {info['days_remaining']}")
        self.lbl_activated.setText(f"Activated: {info['activated_on']}")
        self.lbl_expires.setText(f"Expires: {info['expires']}")
        self.lbl_device_id.setText(f"Device ID: {info['device_id']}")
        self.lbl_bios_serial.setText(f"BIOS Serial: {info['bios_serial']}")
        self.status_label.setText(self.license_mgr.human_status())


