ip_file_path.setReadOnly(True)
ip_file_path.setPlaceholderText("Select text file containing IP addresses")
file_layout.addWidget(ip_file_path)
browse_button = QPushButton("Browse...")
browse_button.clicked.connect(browse_file)
file_layout.addWidget(browse_button)
