about_button.clicked.connect(show_about)
how_to_work_button = QPushButton("!How to Work!")
how_to_work_button.clicked.connect(show_how_to_work)
activation_button = QPushButton("Activation")
def open_activation_dialog():
    dlg = ActivationDialog(license_manager, window, on_activated=lambda: refresh_license_ui())
    dlg.exec_()
activation_button.clicked.connect(open_activation_dialog)

additional_button_layout.addWidget(about_button)
additional_button_layout.addWidget(how_to_work_button)
additional_button_layout.addWidget(activation_button)

# Combine Primary and Additional Buttons in a Vertical Layout
button_layout = QVBoxLayout()
button_layout.addLayout(primary_button_layout)  # Add primary buttons
button_layout.addLayout(additional_button_layout)  # Add additional buttons below

# Add the combined button layout to the left layout
left_layout.addLayout(button_layout)

# Progress Bar
progress_bar = QProgressBar()
progress_bar.setAlignment(Qt.AlignCenter)
left_layout.addWidget(progress_bar)

# Connection Issues Group
error_group = QGroupBox("Connection Issues")
