output_text = QTextEdit()
output_text.setReadOnly(True)
output_text.setFont(QFont("Consolas", 10))
output_layout.addWidget(output_text)
output_group.setLayout(output_layout)
main_layout.addWidget(output_group, 50)  # 50% width for right side

# Signal Connections
comms.update_output.connect(output_text.append)
comms.progress_update.connect(progress_bar.setValue)
comms.progress_max.connect(progress_bar.setMaximum)

def update_buttons(run: bool, stop: bool):
    # Respect license state when enabling Start button
    can_run = True
    try:
        can_run = license_manager.can_start()
    except Exception:
        can_run = True
    run_button.setEnabled(run and can_run)
    stop_button.setEnabled(stop)

comms.toggle_buttons.connect(update_buttons)

def refresh_license_ui():
    # Refresh button state according to current license status
    update_buttons(True, False)


def handle_errors(invalid, failed, errors):
    report = []
    if invalid:
        report.append("Invalid IP Addresses:\n" + "\n".join(invalid))
    if failed:
        report.append("\nFailed Connections:\n" + "\n".join(failed))
    if errors:
        report.append("\nError Messages:\n" + "\n".join(errors))
    error_text.setPlainText("\n".join(report))


comms.update_errors.connect(handle_errors)

window.setLayout(main_layout)
# Initialize buttons according to current license state at startup
try:
    refresh_license_ui()
except Exception:
    pass
window.show()
sys.exit(app.exec_())


